<?php get_header(); if(have_posts()):while(have_posts()):the_post(); ?><article class="single-wrap"><span class="post-category"><?php $cat=get_the_category(); echo esc_html($cat ? $cat[0]->name : 'Kitchen notes'); ?></span><h1 class="single-title"><?php the_title(); ?></h1><p class="single-dek"><?php echo esc_html(get_the_excerpt()); ?></p><div class="single-featured"><?php circlepress_post_image('full'); ?></div><div class="entry-content"><?php the_content(); ?></div></article><?php endwhile;endif; get_footer(); ?>
